function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (!nums.every(v => Number.isInteger(v) && v >= 0 && v <= 100)) return 'Each value is an integer from 0 to 100.';
  return null;
}

