function numberOfPairs(nums) {
  const count = new Map();
  for (const num of nums) {
    count.set(num, (count.get(num) ?? 0) + 1);
  }

  let pairs = 0;
  for (const freq of count.values()) {
    pairs += Math.floor(freq / 2);
  }
  const leftover = nums.length - 2 * pairs;
  return [pairs, leftover];
}

