function numberOfPairs(nums) {
  const rest = nums.slice();
  let pairs = 0;
  let found = true;
  while (found) {
    found = false;
    for (let i = 0; i < rest.length && !found; i++)
      for (let j = i + 1; j < rest.length && !found; j++)
        if (rest[i] === rest[j]) {
          rest.splice(j, 1);
          rest.splice(i, 1);
          pairs++;
          found = true;
        }
  }
  return [pairs, rest.length];
}

