  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 9);
    const top = [0, 1, 3, 6, 100][int(0, 4)];
    return [Array.from({ length: n }, () => int(0, top))];
  }
  const top = [5, 30, 100][int(0, 2)];
  return [Array.from({ length: 100 }, () => int(0, top))];
}
